// Mentors (Framer CMS collection behind /teams and /teams/<slug>).
// Generated by qa/extract-content.py from qa/framer/*.html. Edit by hand only if Framer changes.
export type Mentor = {
  slug: string;
  /** University line shown above the name */
  designation: string;
  name: string;
  description: string;
  image: { src: string; alt: string } | null;
  /** Social icon links in SSR order (each breakpoint variant appears once per pair: V1 = default, V2 = hover). */
  socials: { href: string | null; icon: string | null }[];
  /** Slugs of the course cards shown on the profile */
  courses: string[];
};
